    P=project;
    const people=Math.max(4,Number(brief.people)||36),meeting=Math.max(0,Number(brief.meetingRooms)*Number(brief.roomSeats)||0),phone=Math.max(0,Number(brief.phones)||0);
    const drafts=patterns.map(pattern=>concept(pattern,people,meeting,phone,mode==='private'?'private':'hybrid'));
    drafts.sort((a,b)=>draftScore(a,project.broker,mode)-draftScore(b,project.broker,mode)||patterns.indexOf(a.layoutPattern)-patterns.indexOf(b.layoutPattern));
    const best=drafts[0];project.drafts=drafts.slice(0,3);project.activeDraft=best.id;project.objects=best.objects;project.furniture=best.furniture;project.workAreas=best.workAreas||[];project.site.confirmed=true;
    const rows=brokerAssessment(project).rows;
    return {best:best.label,pattern:best.layoutPattern,thumbnail:functionalZoneDiagram(best),rows,gaps:rows.filter(row=>row.status==='Shortfall'),unassessed:rows.filter(row=>row.status==='Not assessed').length,clarify:rows.filter(row=>row.status==='Needs review').length,conceptReview:rows.filter(row=>row.status==='Placed · concept').length};
